mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM user_card_transaction
    WHERE user_card_id = #{userCardId}
    AND res_used_date = #{usedDate}
    AND res_used_amount = #{usedAmount}

        AND res_approval_no = #{approvalNo}


        AND res_approval_no IS NULL


        AND res_used_time = #{usedTime}


        AND res_used_time IS NULL

    AND is_deleted = false
)
